  // корабля — иначе один и тот же залп имел бы два разных законных прочтения.
  const ordered = [...cells].sort((a, b) => a - b);
  let n0 = S.shot0, n1 = S.shot1;
  for (const c of ordered) { if (c < 32) n0 |= 1 << c; else n1 |= 1 << (c - 32); }
  const tabs = ordered.map((c) => snapshotTables(c, n0, n1));  // по таблице на клетку

  const keys = new Int32Array(U.aliveN);
  const index = new Map();                        // tupleString -> denseKey
  const order = [];
  for (let i = 0, z = 0; i < U.aliveN; i++, z += 4) {
    let sig = '';
    for (let t = 0; t < ordered.length; t++) sig += keyWith(tabs[t], U.ships, z) + ',';
    let k = index.get(sig);
    if (k === undefined) { k = order.length; index.set(sig, k); order.push(sig); }
    keys[i] = k;
  }
  const cnt = new Int32Array(order.length);
  for (let i = 0; i < U.aliveN; i++) cnt[keys[i]]++;
  const chosen = chooseBucket(cnt, opts.policy, opts.eps, S.rngDefender);
  let w = 0;
  for (let i = 0, z = 0; i < U.aliveN; i++, z += 4) if (keys[i] === chosen) { copyCfg(U, z, w * 4); w++; }
  U.aliveN = w; S.shot0 = n0; S.shot1 = n1;
  return decodeTuple(order[chosen], ordered);
}

// ЗОНД ПОДСЧЁТА: «сколько клеток кораблей в области R?» Ключ — само число.
function answerCountProbe(U, S, region /* Int32 маска o0/o1 */, opts) {
  const pop = new Uint8Array(U.aliveN);
  const cnt = new Int32Array(13);                 // максимум 12 клеток флота
  for (let i = 0, z = 0; i < U.aliveN; i++, z += 4) {
    const k = popcount2(occ0Of(U, z) & region.o0, occ1Of(U, z) & region.o1);
    pop[i] = k; cnt[k]++;
  }
  const chosen = chooseBucket(cnt, opts.policy, opts.eps, S.rngDefender);
  filterByArray(U, pop, chosen);
  return { count: chosen };
}

// ПОЛЕ ГЕЛЛЕРА: реальность внутри пузыря ПРИШПИЛИВАЕТСЯ. Ключ — полный узор
// занятости внутри R. Бог обязан выбрать один узор и жить с ним вечно.
function answerGellerField(U, S, region, opts) {
  const sig = new Int32Array(U.aliveN * 2);
  const index = new Map(); const order = [];
  const bucketOf = new Int32Array(U.aliveN);
  for (let i = 0, z = 0; i < U.aliveN; i++, z += 4) {
    const a = occ0Of(U, z) & region.o0, b = occ1Of(U, z) & region.o1;
    const key = a + ':' + b;
    let k = index.get(key);
    if (k === undefined) { k = order.length; index.set(key, k); order.push([a, b]); }
    bucketOf[i] = k;
  }
  const cnt = new Int32Array(order.length);
  for (let i = 0; i < U.aliveN; i++) cnt[bucketOf[i]]++;
  const chosen = chooseBucket(cnt, opts.policy, opts.eps, S.rngDefender);
  filterByArray(U, bucketOf, chosen);
  // Все клетки R теперь определены во ВСЕХ выживших реальностях — их можно
  // закрасить намертво, и стрелять по ним больше нет смысла: счётчик не дрогнет.
  return { pattern: order[chosen], pinnedCells: cellsOf(region) };
}
